cat > /srv/httpd/serve.pl <<'PERLEOF'
use strict; use warnings;
use IO::Socket::INET;
my $LOG = "/var/log/httpd-test.log";
sub logmsg { open(my $f, '>>', $LOG) or return; print $f "@_\n"; close $f }
my $srv = IO::Socket::INET->new(LocalAddr=>'127.0.0.1', LocalPort=>8081,
                                Listen=>5, ReuseAddr=>1, Proto=>'tcp') or die "bind: $!";
$SIG{INT} = sub { logmsg("shutdown on SIGINT"); close $srv; exit 0 };
logmsg("listening on 127.0.0.1:8081");
while (my $c = $srv->accept()) {
    my $req = <$c> // '';
    my ($path) = $req =~ m{^GET\s+(\S+)};
    $path = '/' unless defined $path;
    $path = '/index.html' if $path eq '/';
    my $body = '';
    if (open(my $f, '<', "/srv/httpd/www$path")) { local $/; $body = <$f>; close $f }
    my $code = length($body) ? '200 OK' : '404 Not Found';
    print $c "HTTP/1.0 $code\r\nContent-Length: " . length($body) . "\r\n\r\n$body";
    close $c;
    logmsg("$path $code");
}
PERLEOF
perl -c /srv/httpd/serve.pl

cat > /srv/httpd/client.pl <<'PERLEOF'
use strict; use warnings;
use IO::Socket::INET;
for my $p ('/index.html', '/data.csv', '/') {
    my $s = IO::Socket::INET->new(PeerAddr=>'127.0.0.1', PeerPort=>8081, Proto=>'tcp')
        or die "connect: $!";
    print $s "GET $p HTTP/1.0\r\n\r\n";
    my $status = <$s> // ''; $status =~ s/\r?\n$//;
    print "$p -> $status\n";
    close $s;
}
PERLEOF
perl -c /srv/httpd/client.pl && perl /srv/httpd/client.pl
